import{_ as t,o as e,c as o,ag as r}from"./chunks/framework.DXGyWiRo.js";const c=JSON.parse('{"title":"开篇：一个运维工程师的 AI 笔记","description":"","frontmatter":{},"headers":[],"relativePath":"posts/ai-ip-opening.md","filePath":"posts/ai-ip-opening.md"}'),i={name:"posts/ai-ip-opening.md"};function n(p,a,s,l,h,u){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="开篇-一个运维工程师的-ai-笔记" tabindex="-1">开篇：一个运维工程师的 AI 笔记 <a class="header-anchor" href="#开篇-一个运维工程师的-ai-笔记" aria-label="Permalink to &quot;开篇：一个运维工程师的 AI 笔记&quot;">​</a></h1><blockquote><p>2026-10-10 · 阅读约 3 分钟</p></blockquote><p>我是 Robin，一个做了多年运维的工程师。K8s、Prometheus 是我的老本行，半夜被报警短信叫醒的日子没少过。</p><p>但这两年，我把越来越多的时间花在了 AI 上。</p><h2 id="为什么转向-ai" tabindex="-1">为什么转向 AI <a class="header-anchor" href="#为什么转向-ai" aria-label="Permalink to &quot;为什么转向 AI&quot;">​</a></h2><p>不是跟风，是有几个很具体的触动。</p><p>第一个触动是效率。以前写一个运维脚本，从查文档到调试，半天没了。现在我把需求描述清楚，AI 帮我搭出初版，我只负责 review 和改关键逻辑。<strong>同样的时间，我能做三倍的事。</strong> 这种体感一旦有过，就回不去了。</p><p>第二个触动是 Karpathy 说的那句话：&quot;The hottest new programming language is English.&quot; 干了这么多年技术，我第一次觉得，表达能力正在变成和写代码同等重要的生产力。</p><p>第三个触动是 Agent。2026 年，Agent 从&quot;玩具&quot;变成了&quot;生产力&quot;——能自己规划、自己执行、自己修正，还能自我改进（比如 Dream-RSI 那套递归自我改进的思路）。运维人最懂&quot;自动化&quot;的价值，而 Agent 是自动化的下一站。</p><h2 id="这个博客写什么" tabindex="-1">这个博客写什么 <a class="header-anchor" href="#这个博客写什么" aria-label="Permalink to &quot;这个博客写什么&quot;">​</a></h2><p>想清楚了，就写三件事，都是我自己真实在折腾的：</p><ol><li><strong>AI 提效实战</strong>：我真实在用的工具、方法和踩过的坑，不写没用过的东西</li><li><strong>Agent 前沿追踪</strong>：从 Dream-RSI 到 Karpathy 的 RSI，把最前沿的进展翻译成工程师能用的东西</li><li><strong>内容创作</strong>：用 AI 做小红书、写东西，验证&quot;一个人就是一支队伍&quot;</li></ol><h2 id="更新节奏" tabindex="-1">更新节奏 <a class="header-anchor" href="#更新节奏" aria-label="Permalink to &quot;更新节奏&quot;">​</a></h2><p>每周一篇，周六见。第一篇先立个 flag，后面全是干货。</p><p>如果你也在从传统技术岗往 AI 转，或者想用 AI 提效，欢迎常来看看。一起走，比一个人快。</p>',15)])])}const d=t(i,[["render",n]]);export{c as __pageData,d as default};
